-- N3 — Unicode case fold. Codex: renaming `É.mov` to `é.mov` leaves the Unicode fold unchanged, but
-- r2's trigger compared SQLite lower(), which is ASCII-only, and refused it. path_fold is the APP's
-- NFC + case fold (diacritics kept), stored; the engine compares stored folds only.
INSERT INTO t_assert VALUES ('N3 SQLite lower() is ASCII-only (why it is never identity)', (SELECT lower('É') = 'É' AND lower('A') = 'a'));
