-- C1 — codex C′ #1/#2 (docs/reviews/codex/codex-review-sqlite-store-parts-1-2a-step-c-2026-10-17.md):
-- REPLACE conflict resolution deletes the row in the way WITHOUT firing its delete trigger unless
-- recursive_triggers is on, so `UPDATE OR REPLACE files … WHERE id = B` onto A's live path deleted A,
-- `INSERT OR REPLACE INTO generations … 99` moved the counter without adoption, and replacing the
-- current history row rewrote it. Two layers now (v1.5): the store sets recursive_triggers on every
-- connection (set here too, so the delete-trigger layer runs under every runner), and BEFORE INSERT /
-- BEFORE UPDATE no-replace triggers refuse the statement before any conflict is resolved — binding a
-- connection that never set the pragma (the sqlite3 shell's default).
PRAGMA recursive_triggers = ON;
INSERT INTO t_assert VALUES ('C1 recursive_triggers on', (SELECT recursive_triggers = 1 FROM pragma_recursive_triggers));
INSERT INTO files (id, content_digest, volume_uuid, volume_case_sensitive, full_path, path_fold, filename, ext, directory, size_bytes, digest_computed_at, digest_source, stream_type, lifecycle, archive_stage) VALUES ('00000000-0000-0000-0000-000000000061', 'cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc', '11111111-1111-1111-1111-111111111111', 0, '/Volumes/C1/a.mov', '/volumes/c1/a.mov', 'a.mov', 'mov', '/Volumes/C1', 100, 1700000000, 'archiveFixity', 'Video+Audio', 'Cataloged', 'None');
INSERT INTO files (id, content_digest, volume_uuid, volume_case_sensitive, full_path, path_fold, filename, ext, directory, size_bytes, digest_computed_at, digest_source, stream_type, lifecycle, archive_stage) VALUES ('00000000-0000-0000-0000-000000000062', 'cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc', '11111111-1111-1111-1111-111111111111', 0, '/Volumes/C1/b.mov', '/volumes/c1/b.mov', 'b.mov', 'mov', '/Volumes/C1', 100, 1700000000, 'archiveFixity', 'Video+Audio', 'Cataloged', 'None');
.print '   (expected refusal: UPDATE OR REPLACE b.mov onto a.mov (would delete row 61 without its delete trigger))'
UPDATE OR REPLACE files SET full_path = '/Volumes/C1/a.mov', path_fold = '/volumes/c1/a.mov' WHERE id = '00000000-0000-0000-0000-000000000062';
.print '   (expected refusal: UPDATE OR REPLACE the id of row 62 onto row 61)'
UPDATE OR REPLACE files SET id = '00000000-0000-0000-0000-000000000061' WHERE id = '00000000-0000-0000-0000-000000000062';
INSERT INTO t_assert VALUES ('C1 both rows still live at their own paths', (SELECT count(*) = 2 FROM files WHERE removal_state IS NULL AND ((id = '00000000-0000-0000-0000-000000000061' AND full_path = '/Volumes/C1/a.mov') OR (id = '00000000-0000-0000-0000-000000000062' AND full_path = '/Volumes/C1/b.mov'))));
.print '   (expected refusal: INSERT OR REPLACE over the generation counter (20 -> 99 without adoption))'
INSERT OR REPLACE INTO generations (id, generation, saved_at, saved_from_host) VALUES (1, 99, 1, 'test');
INSERT INTO t_assert VALUES ('C1 counter intact', (SELECT generation = 20 FROM generations WHERE id = 1));
.print '   (expected refusal: INSERT OR REPLACE over the current history row)'
INSERT OR REPLACE INTO generation_history (generation, committed_at, host, writer, files_live, files_total) VALUES (20, 2, 'x', 'forged', 0, 0);
INSERT INTO t_assert VALUES ('C1 history row intact', (SELECT kind = 'adopt' AND from_generation = 11 FROM generation_history WHERE generation = 20));
.print '   (expected refusal: DELETE a history row)'
DELETE FROM generation_history WHERE generation = 20;
