.print '   (expected refusal: DELETE an import run)'
DELETE FROM import_runs WHERE run_id = 'R-C1';
INSERT INTO t_assert VALUES ('C1 history and run rows kept', (SELECT (SELECT count(*) = 1 FROM generation_history WHERE generation = 20) AND (SELECT count(*) = 1 FROM import_runs WHERE run_id = 'R-C1')));
SELECT 'C1 ok' WHERE (SELECT count(*) FROM t_assert WHERE label LIKE 'C1 %') > 0 AND NOT EXISTS (SELECT 1 FROM t_assert WHERE label LIKE 'C1 %' AND ok IS NOT 1);

