-- fix 2026-10-17 (C′ part 2a): the block as first written named a column `import_run_id` that does
-- not exist (it is `import_run`), gave a 15-character json_row_id and omitted origin / full_path /
-- raw_row — so the INSERT was refused for those reasons and 'F5final ok' printed WITHOUT the
-- json_type CHECK ever being reached. Now the row is valid in every other respect (the array
-- control at ordinal 90002 lands), so the only thing refusing 90001 is the CHECK under test.
.bail off
.print '   (expected refusal: findings as a JSON object, not an array (F5 final))'
INSERT INTO quarantine (origin, import_run, source_ordinal, json_row_id, full_path, size_bytes, reason_code, words, findings, raw_row, quarantined_at, generation)
  VALUES ('import', 'R-main', 90001, '00000000-0000-0000-0000-000000000099', '/Volumes/A/f5-final.mov', 100, 'auditGone', 'words for auditGone', '{"rule":"referenceMovie","needsDecision":true}', '{"id":"00000000-0000-0000-0000-000000000099"}', 1, 5);
INSERT INTO quarantine (origin, import_run, source_ordinal, json_row_id, full_path, size_bytes, reason_code, words, findings, raw_row, quarantined_at, generation)
  VALUES ('import', 'R-main', 90002, '00000000-0000-0000-0000-000000000099', '/Volumes/A/f5-final.mov', 100, 'auditGone', 'words for auditGone', '[{"rule":"referenceMovie","needsDecision":true}]', '{"id":"00000000-0000-0000-0000-000000000099"}', 1, 5);
